# backend/app/filter.py (Ausschnitt): aus dem Filter wird eine WHERE-Klausel mit Platzhaltern
def where_klausel(filter):
    bedingungen, werte = [], {}
    if filter.hotel:
        bedingungen.append("h.hotel = :hotel")
        werte["hotel"] = filter.hotel
    if filter.jahr:
        bedingungen.append("d.year = :jahr")
        werte["jahr"] = filter.jahr
    return " AND ".join(bedingungen) or "TRUE", werte

